export function mulberry32(seed: number): () => number {
  let state = seed >>> 0
  return () => {
    state = (state + 0x6d2b79f5) >>> 0
    let t = Math.imul(state ^ (state >>> 15), state | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
`,`/**
 * Distância mínima por rejeição, com grade espacial: o candidato só olha as 27
 * células em volta. Sem distância mínima (0), aceita tudo sem custo.
 */
export function createPoisson(minDistance: number) {
  const grid = new Map<number, number[]>()
  const min2 = minDistance * minDistance
  const cellOf = (v: number) => Math.floor(v / minDistance)
  const key = (x: number, y: number, z: number) => (Math.imul(x, 73856093) ^ Math.imul(y, 19349663) ^ Math.imul(z, 83492791)) | 0

  return {
    /** guarda o ponto se ele respeita a distância de todos os anteriores */
    accept(x: number, y: number, z: number): boolean {
      if (minDistance <= 0) return true
      const cx = cellOf(x)
      const cy = cellOf(y)
      const cz = cellOf(z)
      for (let i = -1; i <= 1; i++) {
        for (let j = -1; j <= 1; j++) {
          for (let k = -1; k <= 1; k++) {
            // célula com colisão de chave só custa uma comparação a mais
            const cell = grid.get(key(cx + i, cy + j, cz + k))
            if (!cell) continue
            for (let p = 0; p < cell.length; p += 3) {
              const dx = cell[p] - x
              const dy = cell[p + 1] - y
              const dz = cell[p + 2] - z
              if (dx * dx + dy * dy + dz * dz < min2) return false
            }
          }
        }
      }
      const own = key(cx, cy, cz)
      const cell = grid.get(own)
      if (cell) cell.push(x, y, z)
      else grid.set(own, [x, y, z])
      return true
    },
  }
}
